mapper.select:
/* 관리자 댓글 목록 조회 : 삭제된 댓글 원문 포함, DEL_YN 조건 없음 */ SELECT C.CMNT_SN , C.PRNT_CMNT_SN , C.PST_SN , P.PST_TTL , C.MBR_SN , M.MBR_NCNM , C.CMNT_CN , CASE WHEN C.DEL_YN = 'Y' THEN 1 ELSE 0 END AS DEL_FLAG , CASE WHEN C.SYS_AUTO_CRT_YN = 'Y' THEN 1 ELSE 0 END AS SYS_AUTO_CRT_FLAG , C.REG_DT FROM CMNT C JOIN PST P ON P.PST_SN = C.PST_SN JOIN MBR M ON M.MBR_SN = C.MBR_SN
AND C.PST_SN = #{cond.pstSn}
AND C.MBR_SN = #{cond.mbrSn}
AND M.MBR_NCNM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY C.REG_DT DESC , C.CMNT_SN DESC
